const baseV3={render,nav,pages,profilePage,attendancePage,peoplePage,accessPage,compensationPage,handleAction,handleSubmit,taskModal,outcomeTask,chatModal,go};
const v3={scenario:'today',expanded:null,personFilter:'all',peopleTab:'people',attendanceTab:'records',day:'2026-09-18',chatUnread:1,serial:1,slipSerial:9};
const policyDefaults=[
 ['approval','Verifikasi & persetujuan','Verification & approvals','nextday',1,1,'Keputusan yang belum selesai diprioritaskan saat tanggal berganti, termasuk akhir pekan. Bukan batas 24 jam.','Unresolved decisions become a priority at the next date change, including weekends. Not an elapsed 24-hour deadline.'],
 ['withdraw','Pencairan royalti','Royalty payouts','monthly',15,2,'Permintaan tanggal 1–14. Prioritas pencairan tanggal 15–20; mulai tanggal 21 melewati periode.','Requests on days 1–14. Payout priority on days 15–20; past the window from day 21.'],
 ['release','Pemeriksaan rilisan','Release review','working',2,3,'Hasil pemeriksaan awal, bukan janji sudah tayang. Jumlah track dan kelengkapan memengaruhi beban.','Initial review outcome, not a go-live promise. Track count and completeness affect effort.'],
 ['delivery','Pengiriman rilisan','Release delivery','working',1,1,'Dihitung setelah disetujui dan semua syarat pengiriman terpenuhi.','Starts after approval and all delivery requirements are met.'],
 ['live','Finalisasi tayang','Go-live checks','release',1,2,'Pemeriksaan kesiapan H−1 hari kerja. Tanggal rilis menjadi acuan hasil, bukan umur antrean.','Readiness check one working day before release. The release date anchors the outcome.'],
 ['support','Respons awal tiket','First ticket response','working',1,2,'Respons bermakna pertama. Penyelesaian mengikuti jenis masalah dan pihak yang ditunggu.','First meaningful response. Resolution depends on the issue and external dependencies.'],
 ['believe','Pemeriksaan Believe','Believe follow-up','working',3,1,'Periksa kembali tiga hari kerja setelah pengiriman atau pemeriksaan tercatat terakhir.','Check again three working days after sending or the last recorded check.'],
 ['label','Menunggu label','Waiting for a label','working',2,1,'Jadwalkan pemeriksaan kelengkapan; waktu tunggu dipisahkan dari waktu penanganan internal.','Schedule a completeness check; waiting time stays separate from internal handling.'],
 ['claim','Persiapan klaim akun','Account claim preparation','working',2,3,'Pencocokan bahan dan bukti. Keputusan akhir memakai aturan persetujuan.','Match records and evidence. Final decisions follow the approval rule.'],
 ['addon','Persiapan layanan & WAMI','Services & WAMI preparation','working',3,2,'Batas persiapan internal. Hasil pihak luar tidak dianggap sebagai durasi kerja staf.','Internal preparation window. External delivery is not treated as staff working time.'],
 ['refund','Pemeriksaan refund','Refund review','working',1,2,'Periksa kelayakan kasus; persetujuan dan pembayaran dicatat sebagai tahap terpisah.','Check eligibility; approval and payment remain separate stages.']
];
function seedV3(){
 data.workRules=policyDefaults.map(a=>({id:a[0],name:[a[1],a[2]],mode:a[3],value:a[4],weight:a[5],desc:[a[6],a[7]],end:20,version:1}));
 data.ops=[{id:'AP-201',title:['Verifikasi identitas · Senja Records','Identity verification · Senja Records'],kind:'approval',area:'platform',created:'2026-09-18',status:'pending',detail:['Dokumen dan data akun cocok. Tinjau hasil pemeriksaan sebelum memutuskan.','Documents match the account. Review the findings before deciding.']},{id:'AP-202',title:['Perubahan metadata · Ruang Senja','Metadata change · Ruang Senja'],kind:'approval',area:'platform',created:'2026-09-17',status:'pending',detail:['Nama pencipta: A. Putra → Andi Putra. Pengusul: Adovi. Bukti koreksi terlampir dalam simulasi.','Writer: A. Putra → Andi Putra. Submitted by Adovi. Correction evidence is simulated.']},{id:'WD-091',title:['Penarikan · Senja Records','Withdrawal · Senja Records'],kind:'withdraw',area:'platform',created:'2026-09-10',status:'pending',detail:['Periode September · verifikasi rekening dan nominal sebelum pencairan.','September cycle · verify the bank and amount before payout.']},{id:'WD-092',title:['Penarikan · Utara Music','Withdrawal · Utara Music'],kind:'withdraw',area:'platform',created:'2026-09-12',status:'approved',detail:['Verifikasi selesai. Pembayaran belum tercatat.','Verification complete. Payment is not recorded yet.']}];
 data.ops.forEach(x=>x.policy={...data.workRules.find(r=>r.id===x.kind)});
 data.slips=[];people.forEach(p=>['2026-07','2026-08'].forEach((m,i)=>data.slips.push({id:'SL-'+p.id+'-'+m,staff:p.id,month:m,status:'issued',version:1,rows:payments(p.id,m).map(x=>({...x})),note:'',created:'2026-09-01'})));
 data.todayDone=people.flatMap((p,j)=>Array.from({length:[2,1,4,3][j]},(_,i)=>({id:'D-'+p.id+'-'+i,staff:p.id,title:titles[(i+j)%titles.length],kind:i%2?'support':'release',time:`${9+i}:25`}))); 
 data.tasks.forEach(x=>{x.ruleVersion=1;x.created='2026-09-18';if(x.last)x.last='2026-09-18'+x.last.slice(10);x.due=x.stage==='believe'?'2026-09-17':x.stage==='correction'?'2026-09-22':'2026-09-21';x.overdue=x.id==='R-1048';});
 data.events=data.events.map(e=>({...e,day:'2026-09-18'}));
}
seedV3();
function day(){return v3.day;}
function operationalTasks(){return visibleTasks().filter(x=>x.stage!=='done');}
function taskAttention(x){if(v3.scenario==='quiet')return false;return x.stage==='approval'?x.last?.slice(0,10)<day():x.due<day();}
function opPriority(x){if(v3.scenario==='quiet')return false;const p=x.policy||data.workRules.find(r=>r.id===x.kind);return x.kind==='withdraw'?Number(day().slice(-2))>=p.value:(p.immediate||x.created<day());}
function opLabel(x){if(x.kind==='withdraw'){const d=Number(day().slice(-2)),p=x.policy||data.workRules.find(r=>r.id==='withdraw');return d>p.end?t('Melewati periode','Past payout window'):d>=p.value?t('Pencairan periode ini','Payout window open'):t('Terjadwal 15–20','Scheduled 15–20');}return opPriority(x)?t('Prioritas hari ini','Priority today'):t('Permintaan hari ini','Requested today');}
function deck(id,title,sub,body,size=6,action=''){const expanded=v3.expanded===id;return `<section class="panel grid-card span-${expanded?12:size} ${expanded?'expanded':''}" data-card="${id}"><div class="panel-head"><div><h2>${title}</h2><p>${sub}</p></div><div class="inline">${action}${btn(icon(expanded?'close':'eye'),'expand',`data-id="${id}" aria-expanded="${expanded}" aria-label="${expanded?t('Ringkas','Collapse'):t('Perluas','Expand')} ${title}"`,'expand-button')}</div></div><div class="body">${body}</div></section>`;}
pages=function(){return {...baseV3.pages(),profile:t('Kinerja Saya','My Performance'),people:t('Staff & Akses','Staff & Access'),workrules:t('Aturan Pekerjaan','Work Rules')};};
nav=function(){if(state.mode==='platform')return [['dashboard','grid'],...(me().super?[['workrules','settings']]:[])];return [['overview','grid'],['profile','activity'],['compensation','wallet'],['attendance','calendar'],...(canTeam()?[['people','people']]:[]),...(me().super?[['logs','shield']]:[])];};
const scenarios=()=>[['today',t('Hari kerja · 18 Sep','Working day · Sep 18')],['tomorrow',t('Hari berganti · 19 Sep','Next day · Sep 19')],['payout',t('Pencairan · 15 Sep','Payout · Sep 15')],['late',t('Lewat periode · 21 Sep','Past window · Sep 21')],['quiet',t('Hari tenang','Quiet day')],['busy',t('Antrean ramai','Busy queue')]];
render=function(){
 baseV3.render();
 if(state.mode==='staff')$('.mode-switch').insertAdjacentHTML('afterend',`<div class="sidebar-person">${portrait(me())}<div><small>${t('Halo,','Hello,')}</small><strong>${esc(me().name)}</strong><span>${personLabel(me())}</span></div></div>`);
 $('.demo-bar').innerHTML=`<div class="inline"><span class="version-pill">V3</span><span>${t('Studio pratinjau','Preview studio')}</span><span class="demo-separator">/</span><small>${date(day())} · ${t('data simulasi','simulated data')}</small></div><div class="inline"><select id="scenario" class="demo-select" aria-label="${t('Skenario demo','Demo scenario')}" ${state.preview?'disabled':''}>${scenarios().map(([v,l])=>`<option value="${v}" ${v3.scenario===v?'selected':''}>${l}</option>`).join('')}</select><select id="demo-user" class="demo-select" ${state.preview?'disabled':''} aria-label="${t('Akun demonstrasi','Demonstration account')}">${people.map(p=>`<option value="${p.id}" ${p.id===state.user?'selected':''}>${p.name} · ${personLabel(p)}</option>`).join('')}</select>${btn(icon('spark'),'simulate','','text')}${btn('?','guide','','text')}</div>`;
 const cb=$('[data-action="chat"]');if(v3.chatUnread)cb.insertAdjacentHTML('beforeend','<i class="dot attention-dot"></i>');
 document.querySelectorAll('.calendar .date').forEach(c=>{c.tabIndex=0;c.setAttribute('role','button');c.setAttribute('aria-label',c.title);});
 document.querySelectorAll('.iconbtn .dot').forEach(d=>d.classList.add('attention-dot'));
 if(state.page==='attendance'&&me().super){$('.pagehead').insertAdjacentHTML('afterend',`<div class="tabs"><button data-action="attendance-view" data-value="records" class="${v3.attendanceTab==='records'?'active':''}">${t('Catatan & pengajuan','Records & requests')}</button><button data-action="attendance-view" data-value="policy" class="${v3.attendanceTab==='policy'?'active':''}">${t('Kebijakan','Policies')}</button></div>`);}
};
function filterTaskRows(a,id){let list=a;if(v3.personFilter!=='all')list=list.filter(x=>x.handler===v3.personFilter);return list.slice(0,v3.expanded===id?30:4).map(taskRow).join('')||empty(t('Belum ada penanganan dalam tampilan ini','No work being handled in this view'));}
taskRow=function(x){const attention=taskAttention(x);return `<div class="task-row compact-task"><div class="task-main"><button class="title" data-action="task" data-id="${x.id}">${esc(splitLabel(x.title))}</button><small>${esc(x.label)} · ${x.id}</small></div><div class="task-status">${badge(stageName(x.stage),attention?'amber':waiting(x)?'':'blue')}<small>${x.stage==='believe'?t('Periksa respons distributor','Check distributor response'):x.stage==='correction'?t('Menunggu kelengkapan label','Awaiting label information'):x.stage==='approval'?t('Keputusan Super Admin','Super Admin decision'):t('Pemeriksaan tercatat','Review recorded')}</small></div><div class="task-progress">${progress(x.pct)}<small>${x.pct==null?t('Belum terukur','Not measured'):x.pct+'%'}</small></div><div class="task-person">${avatar(person(x.handler)||me())}<small>${person(x.handler)?.name||'—'}<span>${t('Penanganan terakhir','Last handling')}</span></small></div></div>`;};
function queueContent(){const a=operationalTasks().filter(x=>x.stage==='queued');return ['release','claim','support'].filter(k=>permission(k)!=='none').map(k=>{const n=a.filter(x=>x.kind===k).length;return `<button class="queue-tile" data-action="queue" data-kind="${k}"><span class="queue-icon">${icon(k)}</span><span class="grow"><strong>${L(kinds[k])}</strong><small>${n?t('Siap ditindaklanjuti','Ready for action'):t('Tidak ada antrean baru','No new items')}</small></span><b>${n}</b>${icon('chevron')}</button>`;}).join('');}
function opRows(items,limit=4){return items.slice(0,limit).map(x=>`<div class="action-row"><div class="grow"><strong>${L(x.title)}</strong><small>${x.id} · ${x.kind==='withdraw'&&x.status==='approved'?t('Terverifikasi · menunggu pembayaran','Verified · awaiting payment'):opLabel(x)}</small></div>${badge(x.kind==='withdraw'&&Number(day().slice(-2))>20?t('Lewat periode','Past window'):opPriority(x)?t('Prioritas','Priority'):t('Baru','New'),opPriority(x)?'amber':'')}${btn(icon('arrow'),'op-detail',`data-id="${x.id}" aria-label="${t('Tinjau','Review')} ${esc(L(x.title))}"`,'small')}</div>`).join('');}
dashboard=function(){
 const a=operationalTasks(),active=a.filter(x=>x.stage!=='queued'),alerts=a.filter(taskAttention),ops=me().super?data.ops.filter(x=>['pending','approved'].includes(x.status)):[],priority=ops.filter(opPriority),quiet=v3.scenario==='quiet';
 const alertCount=quiet?0:alerts.length+priority.length;
 return pageHead(t('Ruang untuk bekerja.','Make room for good work.'),t(`Selamat datang, ${me().name.split(' ')[0]}. Ini yang perlu perhatianmu hari ini.`,`Welcome, ${me().name.split(' ')[0]}. Here’s what needs your attention today.`),`<div class="date-label">${icon('calendar')} ${date(day())}<small>WIB · ${t('simulasi','simulation')}</small></div>`)+
 `<div class="${alertCount?'focus-banner':'calm-banner'}"><span class="${alertCount?'pulse':''}">${alertCount?'':icon('check')}</span><div class="grow"><strong>${alertCount?t(`${alertCount} pekerjaan perlu perhatian`,` ${alertCount} items need attention`):t('Tidak ada tindak lanjut mendesak','No urgent follow-ups')}</strong><small>${alertCount?t('Keputusan tertunda, pemeriksaan berikutnya, dan periode pencairan.','Pending decisions, scheduled checks, and payout windows.'):t('Lanjutkan pekerjaan yang sudah berjalan.','Continue the work already underway.')}</small></div>${alertCount?btn(t('Tinjau prioritas','Review priorities'),'priorities','','small'):''}</div>`+
 `<div class="operational-strip">${[[t('Antrean baru','New queue'),a.filter(x=>x.stage==='queued').length,'new'],[t('Dalam penanganan','Being handled'),active.length,'active'],[t('Menunggu pihak lain','Waiting on others'),active.filter(waiting).length,'waiting'],[t('Selesai hari ini','Completed today'),todayRecords().filter(x=>me().super||x.staff===me().id).length,'done']].map(([s,n,k])=>`<button data-action="stat-detail" data-id="${k}"><span>${s}</span><strong>${n}</strong>${icon('arrow')}</button>`).join('')}</div>`+
 `<div class="dashboard-grid">${deck('queue',t('Antrean Pekerjaan','Work Queue'),t('Pekerjaan yang perlu kamu tindak lanjuti.','Work that needs your next step.'),queueContent(),6)}${deck('mywork','My Work',me().super?t('Keputusanmu menjaga pekerjaan tetap bergerak.','Your decisions keep work moving.'):t('Tanggung jawab bersama berdasarkan role.','Shared responsibility based on your role.'),me().super?(myDecisionRows()+opRows(ops,v3.expanded==='mywork'?30:2)+`${v3.expanded!=='mywork'&&ops.length>2?btn(t('Lihat semua keputusan','View all decisions'),'expand','data-id="mywork"','text'):''}<p class="scope-note">${t('Approval internal staf berada di Staff Overview.','Internal staff approvals are in Staff Overview.')}</p>`):a.filter(x=>x.stage==='queued').slice(0,v3.expanded==='mywork'?30:3).map(x=>`<div class="action-row"><div class="grow"><strong>${esc(splitLabel(x.title))}</strong><small>${x.id} · ${esc(x.label)}</small></div>${btn(t('Lihat','View'),'task',`data-id="${x.id}"`,'small')}</div>`).join('')||empty(t('Antrean sudah bersih','Your queue is clear')),6)}
 ${deck('progress','In Progress',t('Tahapan nyata · semua penanganan dalam cakupanmu.','Real stages · all handling within your scope.'),`<div class="progress-toolbar"><div class="legend"><span class="legend-dot"></span>${t('Persentase tahapan, bukan kecepatan kerja','Stage progress, not work speed')}</div><select id="handler-filter" aria-label="${t('Filter penanganan','Filter handling')}"><option value="all">${t('Semua penanganan','All handling')}</option>${people.map(p=>`<option value="${p.id}" ${v3.personFilter===p.id?'selected':''}>${p.name}</option>`).join('')}</select></div>${filterTaskRows(active,'progress')}${active.length>4&&v3.expanded!=='progress'?`<p class="scope-note">${t(`${active.length-4} pekerjaan lainnya · perluas untuk melihat`,` ${active.length-4} more items · expand to view`)}</p>`:''}`,12)}
 ${deck('summary',t('Ringkasan Platform','Platform Summary'),t('Periode dijelaskan pada tiap indikator · data simulasi.','Periods shown for each indicator · simulated data.'),platformSummary(),8,btn(t('Definisi','Definitions'),'metrics','','text'))}
 ${deck('activity',t('Aktivitas Operasional','Operational Activity'),t('Perubahan terbaru pada pekerjaan dan layanan.','Recent changes to work and services.'),activityRows(v3.expanded==='activity'?30:4),4,btn(t('Semua','All'),'activity','','text'))}</div>`;
};
function miniChart(values,color,desc){const mx=Math.max(...values,1),pts=values.map((v,i)=>`${i*160/(values.length-1)},${37-v/mx*31}`).join(' ');return `<svg class="mini-chart" viewBox="0 0 160 42" preserveAspectRatio="none" role="img" aria-label="${esc(desc)}"><polygon points="0,42 ${pts} 160,42" fill="${color}" opacity=".09" stroke="none"/><polyline points="${pts}" fill="none" stroke="${color}" stroke-width="2"/></svg>`;}
platformSummary=function(){const list=[
 [t('Pendapatan layanan','Service revenue'),money(1120000),t('Agustus · +12% dibanding Juli','August · +12% vs July'),[100,140,180,220,200,280],'var(--green)'],
 ...(me().super?[[t('Penarikan periode ini','Period withdrawals'),money(99215767),t('September · 75 jt dibayar · 24,2 jt menunggu','September · 75m paid · 24.2m pending'),[75,24.215767],'var(--amber)'],[t('Pendapatan royalti','Royalty income'),money(151641563),t('Laporan Juni · tren laporan terakhir','June report · recent report trend'),[58,70,68,103,126,151.64],'var(--blue)']]:[]),
 [t('Total label','Total labels'),fmt(1772),t('+50 pada Agustus','+50 in August'),[6,9,5,12,8,10],'var(--accent)'],
 [t('Total artis','Total artists'),fmt(6756),t('+111 pada Agustus','+111 in August'),[10,24,13,19,20,25],'var(--blue)'],
 [t('Total rilisan','Total releases'),fmt(17931),t('+260 pada Agustus','+260 in August'),[32,51,28,49,42,58],'var(--green)'],
 [t('Label aktif','Active labels'),'171',t('Akun label · bukan jumlah staf','Label accounts · not staff count'),[144,150,153,162,167,171],'var(--accent)']];
 return `<div class="summary-grid">${list.map(([l,n,s,v,c],i)=>`<div class="summary-stat"><small>${l}</small><strong>${n}</strong>${me().super&&i===1?`<div class="payout-bar" role="img" aria-label="${s}"><span style="width:75.6%;background:var(--green)"></span><span style="width:24.4%;background:var(--amber)"></span></div>`:miniChart(v,c,l+' · '+t('seri contoh','sample series')+' '+v.join(', '))}<p>${s}</p></div>`).join('')}</div>`;
};
function todayRecords(){return ['today','quiet','busy'].includes(v3.scenario)?data.todayDone:[];}
function attendanceToday(p){const d=day(),off=!data.policy.days.includes(new Date(d+'T12:00Z').getUTCDay())||data.holidays.includes(d),leave=data.leaves.some(x=>x.staff===p.id&&['approved','used'].includes(x.status)&&x.start<=d&&x.end>=d);if(off)return {label:t('Libur','Day off'),time:'—',color:''};if(leave)return {label:t('Cuti','On leave'),time:'—',color:'blue'};if(!['today','quiet','busy'].includes(v3.scenario))return {label:t('Belum tercatat','Not recorded'),time:'—',color:''};const time={jeck:'07:56',eka:'08:03',adovi:'08:24',cantika:'07:58'}[p.id],minutes=s=>Number(s.slice(0,2))*60+Number(s.slice(3));const late=minutes(time)>minutes(data.policy.start)+data.policy.grace;return {label:late?t('Terlambat','Late'):t('Tepat waktu','On time'),time,color:late?'amber':'green'};}
function attendanceCards(){return `<div class="presence-grid">${people.map(p=>{const s=attendanceToday(p);return `<button class="presence" data-action="person-overview" data-id="${p.id}">${avatar(p)}<div class="grow"><strong>${p.name}</strong><small>${personLabel(p)}</small></div><div class="num">${badge(s.label,s.color)}<small>${s.time}${s.time!=='—'?' WIB':''}</small></div></button>`;}).join('')}</div>`;}
function staffEvents(){return data.events.filter(e=>e.who&&e.day===day());}
function workLoad(){const tasks=data.tasks.filter(x=>x.stage!=='done'),max=Math.max(...people.map(p=>tasks.filter(x=>x.handler===p.id).length+todayRecords().filter(x=>x.staff===p.id).length),1);return `<div class="legend"><span><i style="background:var(--blue)"></i>${t('Penanganan terakhir','Last handling')}</span><span><i style="background:var(--green)"></i>${t('Selesai hari ini','Completed today')}</span></div>${people.map(p=>{const active=tasks.filter(x=>x.handler===p.id),done=todayRecords().filter(x=>x.staff===p.id).length;const perms=p.super?['release','claim','support']:Object.entries(data.roles.find(r=>r.id===data.assignments[p.id])?.rules||{}).filter(([k,v])=>v!=='none').map(([k])=>k);const queue=tasks.filter(x=>x.stage==='queued'&&perms.includes(x.kind)).length;return `<button class="workload-row" data-action="person-overview" data-id="${p.id}"><div class="spread"><strong>${p.name}</strong><small>${queue} ${t('antrean bersama','shared queue')}</small></div><div class="load-track"><span style="width:${active.length/max*100}%;background:var(--blue)"></span><span style="width:${done/max*100}%;background:var(--green)"></span></div><div class="spread"><small>${active.length} ${t('ditangani','handled')} · ${done} ${t('selesai','completed')}</small><small>${active.filter(taskAttention).length} ${t('perlu perhatian','need attention')}</small></div></button>`;}).join('')}<p class="scope-note">${t('Antrean role dapat sama antarstaf. Tidak dijumlahkan sebagai beban tim.','Role queues can overlap between staff. They are not summed as team workload.')}</p>`;}
function internalApprovals(){const a=data.leaves.filter(x=>x.status==='pending').map(x=>`<div class="action-row"><div class="grow"><strong>${t('Pengajuan cuti','Leave request')} · ${person(x.staff).name}</strong><small>${date(x.start)} · ${x.days} ${t('hari kerja','working days')}</small></div>${btn(t('Tinjau','Review'),'internal-review',`data-id="${x.id}"`,'small')}</div>`);return a.join('')+data.corrections.filter(x=>x.status==='pending').map(x=>`<div class="action-row"><strong class="grow">${t('Koreksi kehadiran','Attendance correction')} · ${person(x.staff).name}</strong>${btn(t('Tinjau','Review'),'correction-review',`data-id="${x.id}"`,'small')}</div>`).join('')+(a.length?'':empty(t('Tidak ada pengajuan cuti menunggu','No pending leave requests')));}
overview=function(){if(!canTeam())return personalOverview(me().id);const tasks=operationalTasks();return pageHead(t('Hari ini, bersama tim.','Today, with the team.'),t('Kehadiran, pekerjaan nyata, dan hal yang perlu kamu bantu.','Attendance, real work, and where your help is needed.'),`<div class="date-label">${date(day())}<small>${t('Catatan harian simulasi','Simulated daily records')}</small></div>`)+`<div class="dashboard-grid">${deck('presence',t('Kondisi tim hari ini','Your team today'),t('Jam kehadiran tercatat · status online tidak menentukan absensi.','Recorded arrival time · online status does not determine attendance.'),attendanceCards(),12)}<section class="span-12 staff-metrics"><div class="operational-strip">${[[t('Antrean bersama','Shared queue'),tasks.filter(x=>x.stage==='queued').length,'new'],['In Progress',tasks.filter(x=>x.stage!=='queued').length,'active'],[t('Selesai hari ini','Completed today'),todayRecords().length,'done'],[t('Tindak lanjut terlambat','Overdue follow-ups'),tasks.filter(x=>x.stage!=='approval'&&taskAttention(x)).length,'overdue']].map(([l,n,k])=>`<button data-action="stat-detail" data-id="${k}"><span>${l}</span><strong>${n}</strong>${icon('arrow')}</button>`).join('')}</div></section>${deck('workload',t('Aktivitas & Tanggung Jawab','Activity & Responsibility'),t('Kontribusi setiap orang, tanpa ranking.','Each person’s contribution, without rankings.'),workLoad(),7)}${deck('staff-activity',t('Aktivitas Staf','Staff Activity'),t('Tindakan internal yang tercatat hari ini.','Internal actions recorded today.'),staffEvents().slice(0,v3.expanded==='staff-activity'?30:4).map(e=>`<div class="activity">${avatar(person(e.who))}<div class="grow"><strong>${person(e.who).name}</strong><p>${esc(L(e.text))}</p><small>${e.obj}</small></div><time>${e.time}</time></div>`).join('')||empty(t('Belum ada aktivitas pada tanggal ini','No activity on this date')),5)}${me().super?deck('staff-approvals',t('Keputusan Internal','Internal Decisions'),t('Pengajuan staf · data pendapatan tetap di menu kompensasi.','Staff requests · earnings remain in Compensation.'),internalApprovals(),12):''}</div>`;};
function personalOverview(id){const p=person(id),s=attendanceToday(p),m=perf(id),prev=perf(id,'2026-07'),done=todayRecords().filter(x=>x.staff===id).length;return pageHead(t('Ruang untuk bertumbuh.','Room to grow.'),t('Kenali kontribusimu, jaga kualitasmu.','Know your contribution. Keep quality in focus.'))+`<section class="personal-overview"><div class="portrait-column">${portrait(p)}<span class="portrait-caption">RILIS MUSIK / ${p.initials}</span></div><div class="personal-intro"><div class="inline">${badge(personLabel(p))}<span class="award" tabindex="0" title="${t('Catatan kerja dapat ditelusuri pada periode Juli–Agustus. Badge simulasi, tanpa ranking.','Work records are traceable across July–August. Simulated badge, no ranking.')}">${icon('shield')}${t('Kontribusi tercatat','Traceable contribution')}</span></div><h1>${p.name}</h1><p class="sub">${t('Setiap pekerjaan yang baik meninggalkan jejak.','Good work leaves a meaningful trace.')}</p><div class="personal-daily"><div><small>${t('Kehadiran hari ini','Today’s attendance')}</small><strong>${s.time}</strong>${badge(s.label,s.color)}</div><div><small>${t('Selesai hari ini','Completed today')}</small><strong>${done}</strong><small>${t('Tahapan kerja','Work stages')}</small></div><div><small>${t('Penanganan terakhir','Last handling')}</small><strong>${data.tasks.filter(x=>x.handler===id&&x.stage!=='done').length}</strong><small>${t('Pekerjaan berjalan','Ongoing items')}</small></div></div><div class="inline space">${btn(t('Informasi pribadi','Personal information'),'personal',`data-id="${id}"`,'small')}${btn(t('Kontrak kerja','Employment contract'),'contract',`data-id="${id}"`,'small')}${btn(t('Lihat kinerja','View performance'),'profile',`data-id="${id}"`,'primary')}</div><p class="scope-note">${t('Bergabung','Joined')} ${date(p.joined)} · PKWTT · ${t('Aktif','Active')} · ${esc(data.profiles[id].location)}</p></div></section><div class="dashboard-grid">${deck('my-month',t('Perjalanan dua bulan','Your two-month journey'),t('Hasil nyata, disertai konteks kualitas.','Real outcomes with quality context.'),`<div class="month-comparison"><div><small>${t('Juli','July')}</small><strong>${prev.total}</strong></div><span>→</span><div><small>${month()}</small><strong>${m.total}</strong></div><p>${t('tahapan selesai','completed stages')}<br><small>${m.corrections} ${t('koreksi internal','internal corrections')}</small></p></div>${weeklyChart(id)}`,5)}${deck('my-review',t('Ulasan untukmu','Your monthly reflection'),month()+' · '+t('AI simulasi berbasis catatan','Simulated AI based on records'),`<p class="reflection">${t(`${m.total} tahapan selesai, ${m.on} di antaranya tepat waktu. Ada ${m.corrections} koreksi internal yang dapat menjadi bahan perbaikan.`,`${m.total} stages completed, ${m.on} on time. ${m.corrections} internal corrections offer opportunities to improve.`)}</p><div class="insight"><strong>${t('Jaga kualitas sebelum meneruskan','Keep quality in focus')}</strong><p>${t('Periksa kelengkapan pemegang hak. Kecepatan perlu dibaca bersama kualitas dan jenis pekerjaan.','Check rights-holder completeness. Speed should be considered alongside quality and work type.')}</p></div>${btn(t('Buka ulasan & bukti lengkap','Open full review & evidence'),'profile',`data-id="${id}"`,'text')}`,7)}</div>`;}
profilePage=function(){const id=state.profile||me().id;let html=baseV3.profilePage().replace(/^<div class="spread"[\s\S]*?<\/select><\/div>/,'');html=html.replace(/<section class="profile-hero">[\s\S]*?<\/section>/,pageHead(id===me().id?t('Kinerja Saya','My Performance'):t('Kinerja','Performance')+' · '+esc(person(id).name),t('Hasil, kualitas, dan ketepatan waktu dalam satu pandangan.','Outcomes, quality, and timeliness in one view.'),periodPicker()));html=html.replaceAll(t('Profil & Kinerja','Profile & Performance'),t('Kinerja','Performance'));const m=perf(id);return html+`<div class="grid equal space">${panel(t('Kualitas penyelesaian','Completion quality'),`<div class="quality-stat"><strong>${m.total?Math.round((m.total-m.corrections)/m.total*100):0}%</strong><span>${t('tanpa koreksi internal tercatat','without recorded internal correction')}</span></div>${progress(m.total?(m.total-m.corrections)/m.total*100:0)}<p class="scope-note">${t('Bukan jaminan bebas kesalahan. Hanya mengukur koreksi yang tercatat dalam simulasi.','Not a guarantee of error-free work. Measures only corrections recorded in this simulation.')}</p>${btn(t('Periksa catatan koreksi','Inspect correction records'),'history',`data-id="${id}" data-filter="correction"`,'text')}`)}${panel(t('Waktu & konteks','Timing & context'),`<div class="row"><span>${t('Waktu antre','Queue duration')}</span>${badge(t('Belum terukur','Not measured'))}</div><div class="row"><span>${t('Durasi kerja aktif','Active work duration')}</span>${badge(t('Belum terukur','Not measured'))}</div><p class="scope-note">${t('Riwayat hasil tersedia. Timestamp tahap yang belum lengkap tidak diubah menjadi angka durasi atau skor.','Outcome history is available. Incomplete stage timestamps are not turned into duration estimates or scores.')}</p>`)}</div>`;};
attendancePage=function(){if(me().super&&v3.attendanceTab==='policy')return settingsPage();return baseV3.attendancePage().replace(/<p class="scope-note">Status hari ini:[\s\S]*?<\/p>/,'').replace(/<p class="scope-note">Today: Saturday[\s\S]*?<\/p>/,'')+`<div class="notice space">${t('Kalender laporan mengikuti periode terpilih. Kondisi hari ini mengikuti tanggal skenario demo. Klik tanggal kalender untuk melihat catatan.','The report calendar follows the selected period. Today’s status follows the demo date. Click a calendar date to inspect the record.')}</div>`;};
peoplePage=function(){if(!canTeam())return '';if(v3.peopleTab==='roles'&&me().super)return `<div class="tabs"><button data-action="people-tab" data-value="people">${t('Staff','Staff')}</button><button class="active" data-action="people-tab" data-value="roles">${t('Role & Izin','Roles & Permissions')}</button></div>`+baseV3.accessPage();return pageHead(t('Orang di balik setiap hasil.','People behind every outcome.'),t('Empat staf. Tanggung jawab mengikuti role, tanpa penugasan tambahan.','Four staff. Responsibility follows roles, without extra assignment.'))+`<div class="tabs"><button class="active" data-action="people-tab" data-value="people">Staff</button>${me().super?`<button data-action="people-tab" data-value="roles">${t('Role & Izin','Roles & Permissions')}</button>`:''}</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>${t('Nama','Name')}</th><th>${t('Bergabung','Joined')}</th><th>${t('Role operasional','Operational role')}</th><th>${t('Status','Status')}</th><th></th></tr></thead><tbody>${people.map(p=>`<tr><td>${personCell(p)}</td><td>${date(p.joined)}</td><td>${p.super?t('Seluruh kewenangan','Full authority'):esc(splitLabel(data.roles.find(r=>r.id===data.assignments[p.id])?.name||'—'))}</td><td>${badge(t('Aktif','Active'),'green')}</td><td><div class="team-actions">${btn('Overview','person-overview',`data-id="${p.id}"`,'small')}${me().super&&!p.super?btn(t('Role','Role'),'assign',`data-id="${p.id}"`,'small')+btn(icon('eye'),'preview',`data-id="${p.id}" aria-label="${t('Pratinjau','Preview')} ${p.name}"`,'small'):''}${me().super?btn(t('Edit','Edit'),'personal',`data-id="${p.id}"`,'small'):''}</div></td></tr>`).join('')}</tbody></table></div></section>`;};
function ruleValue(r){return r.mode==='nextday'?(r.immediate?t('Langsung saat masuk','Immediately on arrival'):t('Hari berikutnya','Next calendar day')):r.mode==='monthly'?`${r.value}–${r.end} ${t('setiap bulan','each month')}`:r.mode==='release'?`H−${r.value} ${t('hari kerja','working day')}`:`${r.value} ${t('hari kerja','working days')}`;}
function workRulesPage(){if(!me().super)return '';return pageHead(t('Aturan yang punya alasan.','Rules with a reason.'),t('Dasar antrean, pengingat, dan kontribusi. Dapat disesuaikan tanpa mengubah role staf.','The foundation for queues, reminders and contributions. Adjustable without changing staff roles.'))+`<div class="notice blue">${t('Aturan prioritas hari berikutnya dan pencairan 15–20 mengikuti keputusanmu. Durasi operasional lainnya adalah usulan awal simulasi, bukan standar kinerja final.','Next-day priority and payouts on days 15–20 follow your decisions. Other operating durations are initial simulated proposals, not final performance standards.')}</div><section class="panel"><div class="table-wrap"><table class="rules-table"><thead><tr><th>${t('Tahap pekerjaan','Work stage')}</th><th>${t('Aturan awal / aktif','Initial / active rule')}</th><th>${t('Bobot tahap','Stage weight')}</th><th></th></tr></thead><tbody>${data.workRules.map(r=>`<tr><td><strong>${L(r.name)}</strong><small>${L(r.desc)}</small></td><td>${ruleValue(r)}<small>v${r.version} · ${t('pekerjaan baru','new work')}</small></td><td>${r.weight} / 3</td><td>${btn(t('Atur','Configure'),'rule-edit',`data-id="${r.id}"`,'small')}</td></tr>`).join('')}</tbody></table></div></section><div class="grid equal space">${panel(t('Cara waktu dihitung','How time is counted'),`<div class="row"><strong>${t('Mulai','Start')}</strong><span>${t('Saat siap ditindaklanjuti','When ready for action')}</span></div><div class="row"><strong>${t('Berhenti','Stop')}</strong><span>${t('Hasil tahap tersimpan','Stage outcome saved')}</span></div><p class="sub">${t('Hari kerja mengikuti kebijakan kehadiran. Menunggu pihak luar dicatat terpisah. Membuka halaman tidak mengulang hitungan waktu.','Working days follow attendance policy. External waiting is separate. Opening a page does not reset a clock.')}</p>`)}${panel(t('Bobot bukan penilaian orang','Weights do not rate people'),`<p class="sub">${t('1: pemeriksaan terarah. 2: beberapa komponen. 3: penanganan mendalam. Risiko dan urgensi tetap terpisah; tidak ada ranking atau bonus otomatis.','1: focused check. 2: multiple components. 3: in-depth handling. Risk and urgency stay separate; no ranking or automatic bonus.')}</p>${btn(t('Lihat cakupan pekerjaan','View workflow coverage'),'coverage','','text')}`)}</div>`;}
function ruleModal(id){if(!me().super)return;const r=data.workRules.find(x=>x.id===id);modal(L(r.name),`<p class="sub">${L(r.desc)}</p><form data-form="work-rule" data-id="${id}"><div class="form-grid space">${r.mode==='nextday'?selectField('nextday',t('Menjadi prioritas','Becomes a priority'),[['nextday',t('Saat tanggal berganti · WIB','At the next date change · WIB')],['same',t('Langsung saat masuk','Immediately on arrival')]],r.immediate?'same':'nextday'):field('value',r.mode==='monthly'?t('Mulai pencairan (tanggal)','Payout starts (day)'):t('Jumlah hari kerja','Working days'),r.value,'number',`min="1" max="${r.mode==='monthly'?28:30}" required`)}${r.mode==='monthly'?field('end',t('Akhir pencairan (tanggal)','Payout ends (day)'),r.end,'number','min="1" max="28" required'):''}${selectField('weight',t('Bobot tahap','Stage weight'),[[1,t('1 · Terarah','1 · Focused')],[2,t('2 · Bertahap','2 · Multi-step')],[3,t('3 · Mendalam','3 · In-depth')]],r.weight)}${reasonField()}</div><div id="rule-preview" class="notice space"></div><p class="scope-note">${t('Berlaku untuk pekerjaan baru. Pekerjaan berjalan menyimpan versi dan tenggat sebelumnya. Riwayat perubahan tersimpan dalam sesi ini.','Applies to new work. Existing work retains its previous rule version and deadline. Change history is kept in this session.')}</p>${formEnd(t('Simpan aturan','Save rule'))}</form>`);ruleExample();}
function addWorkingDays(s,n){let d=new Date(s+'T12:00:00Z'),count=0;for(let i=0;i<370&&count<n;i++){d.setUTCDate(d.getUTCDate()+1);if(data.policy.days.includes(d.getUTCDay())&&!data.holidays.includes(d.toISOString().slice(0,10)))count++;}return d.toISOString().slice(0,10);}
function ruleExample(){const f=$('form[data-form="work-rule"]');if(!f)return;const r=data.workRules.find(x=>x.id===f.dataset.id),v=new FormData(f),n=Number(v.get('value'));$('#rule-preview').textContent=r.mode==='nextday'?(v.get('nextday')==='same'?t('Contoh: masuk Senin 23.50 → langsung prioritas.','Example: arrives Monday 23:50 → priority immediately.'):t('Contoh: masuk Senin 23.50 → prioritas Selasa 00.00 WIB. Bukan otomatis overdue.','Example: arrives Monday 23:50 → priority Tuesday 00:00 WIB. Not automatically overdue.')):r.mode==='monthly'?t(`Prioritas tanggal ${n}–${v.get('end')}; melewati periode mulai tanggal ${Number(v.get('end'))+1}.`,`Priority on days ${n}–${v.get('end')}; past the window from day ${Number(v.get('end'))+1}.`):r.mode==='release'?t(`Pemeriksaan ${n} hari kerja sebelum tanggal rilis.`,`Readiness check ${n} working days before release.`):t(`Contoh: siap 18 Sep → tindak lanjut ${date(addWorkingDays('2026-09-18',Math.max(1,Math.min(30,n||1))))}.`,`Example: ready Sep 18 → follow-up ${date(addWorkingDays('2026-09-18',Math.max(1,Math.min(30,n||1))))}.`);}
function opModal(id){if(!me().super)return;const x=data.ops.find(x=>x.id===id);if(!x)return;modal(L(x.title),`${badge(opLabel(x),opPriority(x)?'amber':'blue')}<p class="sub">${L(x.detail)}</p><dl class="facts space"><div><dt>${t('Masuk','Received')}</dt><dd>${date(x.created)}</dd></div><div><dt>${t('Status','Status')}</dt><dd>${statusName(x.status)}</dd></div></dl>${['pending','approved'].includes(x.status)?`<form data-form="op-decision" data-id="${x.id}" class="space">${reasonField()}<div class="inline space"><button type="submit" name="decision" value="approve" class="btn primary">${x.kind==='withdraw'?(x.status==='pending'?t('Verifikasi selesai','Mark verified'):t('Catat sudah dibayar','Record as paid')):t('Setujui','Approve')}</button><button type="button" data-action="op-reject" data-id="${id}" class="btn">${t('Tolak','Decline')}</button></div><div id="form-feedback" role="status"></div></form>`:''}<p class="scope-note">${t('Tindakan demo lokal. Tidak ada transfer atau perubahan akun nyata.','Local demo action. No transfers or real account changes.')}</p>`);}
function compensationSlips(){const team=me().super&&state.comp==='team',rows=data.slips.filter(x=>team||x.staff===me().id&&x.status==='issued');return panel(t('Dokumen & riwayat slip','Payslip documents & history'),`<div class="table-wrap"><table><thead><tr><th>${t('Dokumen','Document')}</th><th>${t('Periode','Period')}</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${person(x.staff).name}<small>${esc(x.id)} · v${x.version}</small></td><td>${month(x.month)}</td><td>${badge(x.status==='issued'?t('Diterbitkan','Issued'):x.status==='void'?t('Dibatalkan','Cancelled'):t('Draf','Draft'),x.status==='issued'?'green':'')}</td><td><div class="team-actions">${btn(icon('download'),'slip-download',`data-id="${x.id}" aria-label="${t('Unduh','Download')} ${esc(x.id)}"`,'small')}${team&&x.status==='draft'?btn(t('Edit','Edit'),'slip-edit',`data-id="${x.id}"`,'small')+btn(t('Terbitkan','Issue'),'slip-issue',`data-id="${x.id}"`,'small')+btn(t('Hapus','Delete'),'slip-delete',`data-id="${x.id}"`,'small'):team&&x.status==='issued'?btn(t('Koreksi','Correct'),'slip-copy',`data-id="${x.id}"`,'small')+btn(t('Batalkan','Cancel'),'slip-void',`data-id="${x.id}"`,'small'):''}</div></td></tr>`).join('')}</tbody></table></div>`,team?btn(t('Buat slip','Create payslip'),'slip-new','','small'):'',t('Slip diterbitkan disimpan sebagai versi; perubahan dokumen tidak mengubah catatan pembayaran.','Issued documents retain their versions; editing a document does not change payment records.'));}
compensationPage=function(){return baseV3.compensationPage()+`<div class="space">${compensationSlips()}</div>`;};
function slipForm(id){if(!me().super)return;const x=data.slips.find(x=>x.id===id);if(x&&x.status!=='draft')return;modal(t('Draf slip gaji','Payslip draft'),`<form data-form="slip" data-id="${id||'new'}"><div class="form-grid">${selectField('staff','Staff',people.map(p=>[p.id,p.name]),x?.staff||'adovi')}${selectField('month',t('Periode','Period'),[['2026-08',month('2026-08')],['2026-07',month('2026-07')]],x?.month||state.period)}${field('adjust',t('Koreksi nominal dokumen (IDR)','Document amount correction (IDR)'),x?.adjust||0,'number','step="1" min="-100000000" max="100000000" required')}${field('note',t('Catatan / alasan','Note / reason'),x?.note||'','text','required maxlength="300"')}</div><p class="scope-note">${t('Rincian diambil dari periode terpilih. Koreksi hanya memengaruhi dokumen, bukan pembayaran.','Details are taken from the selected period. Corrections affect the document, not payments.')}</p>${formEnd(t('Simpan draf','Save draft'))}</form>`);}
async function slipDownload(id){const x=data.slips.find(x=>x.id===id);if(!x||(!me().super&&(x.staff!==me().id||x.status!=='issued'))||previewBlocked())return;const pdf=await PDFLib.PDFDocument.create(),pg=pdf.addPage([595,842]),font=await pdf.embedFont(PDFLib.StandardFonts.Helvetica);let y=780;const line=(txt,size=12)=>{pg.drawText(String(txt).replace(/[^\x20-\x7E]/g,' '),{x:45,y,size,font});y-=size+15;};line('RILIS MUSIK',23);line(t('SLIP PENDAPATAN - SIMULASI','EARNINGS STATEMENT - SIMULATION'),11);line(person(x.staff).name,19);line(month(x.month)+' / '+slipLabel118(x)+' / v'+x.version);line(t('Status: ','Status: ')+x.status);y-=15;x.rows.forEach(r=>line(`${r.label}: IDR ${fmt(r.amount)} / ${r.paid?t('Dibayar','Paid'):t('Belum dibayar','Unpaid')}`));if(x.adjust)line(t('Koreksi dokumen: ','Document correction: ')+fmt(x.adjust));line(t('Total dokumen: IDR ','Document total: IDR ')+fmt(x.rows.reduce((s,r)=>s+r.amount,0)+(x.adjust||0)),15);for(let i=0;i<(x.note||'').length;i+=65)line(x.note.slice(i,i+65),10);line(t('Tidak mengubah catatan pembayaran. Bukan slip resmi.','Does not change payment records. Not an official payslip.'),10);const url=URL.createObjectURL(new Blob([await pdf.save()],{type:'application/pdf'})),a=document.createElement('a');a.href=url;a.download=slipLabel118(x)+'-v'+x.version+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function simulateModal(){modal(t('Studio skenario','Scenario studio'),`<p class="sub">${t('Coba sebab dan akibat. Seluruh kejadian hanya di prototipe lokal.','Explore cause and effect. Every event stays in the local prototype.')}</p><div class="simulation-options space">${btn(t('Balasan chat label masuk','Receive a label chat reply'),'sim-chat','','small')}${btn(t('Notifikasi keputusan masuk','Receive a decision notification'),'sim-notification','','small')}${btn(t('Balasan Believe masuk','Receive a Believe response'),'sim-believe','','small')}${btn(t('Atur ulang semua data','Reset all demo data'),'reset','','small')}</div>`);}
function prioritiesModal(){const a=operationalTasks().filter(taskAttention);modal(t('Perlu perhatian hari ini','Needs attention today'),`${me().super?opRows(data.ops.filter(x=>['pending','approved'].includes(x.status)&&opPriority(x)),30):''}${a.map(x=>`<div class="action-row"><div class="grow"><strong>${esc(splitLabel(x.title))}</strong><small>${x.stage==='approval'?t('Permintaan belum diputuskan sejak kemarin','Decision pending since yesterday'):t('Jadwal pemeriksaan sudah lewat','Scheduled check is overdue')}</small></div>${btn(t('Tinjau','Review'),'task',`data-id="${x.id}"`,'small')}</div>`).join('')}`);}
taskModal=function(id){baseV3.taskModal(id);const x=visibleTasks().find(x=>x.id===id);if(!x||!$('#dialog').open)return;const f=$('form[data-form="task-action"]');if(f&&x.stage==='approval'&&!me().super)f.outerHTML=`<div class="notice space">${t('Menunggu keputusan Super Admin. Kontribusi pemeriksaanmu tetap tercatat.','Awaiting a Super Admin decision. Your review contribution remains recorded.')}</div>`;if(f&&['believe','correction'].includes(x.stage)){f.outerHTML=`<div class="notice space">${x.stage==='believe'?t('Menunggu respons Believe. Pemeriksaan dicatat tanpa menganggap pekerjaan selesai.','Awaiting Believe. A check is recorded without marking the work completed.'):t('Menunggu revisi label. Pemeriksaan tidak mengubah status menjadi selesai.','Awaiting label corrections. A check does not mark work completed.')}</div><form data-form="followup" data-id="${id}">${reasonField()}${formEnd(t('Catat tindak lanjut','Record follow-up'))}</form>`;}}
outcomeTask=function(x,note){if(x.responseReceived&&x.stage==='review'){x.stage='believe';delete x.responseReceived;}baseV3.outcomeTask(x,note);x.last=day()+'T12:00:00';x.due=addWorkingDays(day(),data.workRules.find(r=>r.id==='release').value);x.ruleVersion=data.workRules.find(r=>r.id==='release').version;if(data.events[0])data.events[0].day=day();if(x.stage==='done')data.todayDone.push({id:'D-'+Date.now(),staff:me().id,title:x.title,kind:x.kind,time:'12:00'});};
chatModal=function(){if(!state.preview)v3.chatUnread=0;baseV3.chatModal();const cb=$('[data-action="chat"] .dot');if(cb&&!v3.chatUnread)cb.remove();$('.dialog-body').insertAdjacentHTML('afterbegin',`<div class="chat-demo-line">${badge(t('Percakapan lokal · simulasi','Local conversation · simulation'))}${btn(t('Simulasikan balasan','Simulate reply'),'sim-chat','','text')}</div>`);};
guide=function(){modal(t('Selamat datang di V3','Welcome to V3'),`<p class="reflection">${t('Coba dashboard sebagai Jeck, lalu masuk Staff. Ganti ke Adovi untuk melihat ruang personal dan kinerjanya.','Try the dashboard as Jeck, then enter Staff. Switch to Adovi for the personal overview and performance.')}</p><ol class="guide-list"><li>${t('Perluas In Progress untuk melihat susunan grid berubah.','Expand In Progress to see the grid reflow.')}</li><li>${t('Ganti skenario tanggal untuk prioritas hari berikutnya dan pencairan 15–20.','Change the date scenario for next-day priority and payouts on days 15–20.')}</li><li>${t('Staff & Akses → Role & Izin untuk pratinjau akses tanpa perubahan data.','Staff & Access → Roles & Permissions for read-only access preview.')}</li><li>${t('Kompensasi → Kelola tim untuk membuat dan mengoreksi slip PDF.','Compensation → Manage team to create and correct PDF payslips.')}</li></ol><div class="notice">${t('Data Juli–Agustus, snapshot operasional September 2026. AI adalah simulasi berbasis catatan. Data bisnis di memori tab; muat ulang mengembalikan keadaan awal.','July–August history, September 2026 operational snapshot. AI is a record-based simulation. Business data lives in tab memory; reloading restores initial state.')}</div>${btn(t('Mulai menjelajah','Start exploring'),'close','','primary')}`);};
handleAction=async function(b){const a=b.dataset.action,id=b.dataset.id,value=b.dataset.value;
 if(a==='expand'){v3.expanded=v3.expanded===id?null:id;render();return;}
 if(a==='nav'||a==='search-nav'){if(b.dataset.page==='workrules')return go('workrules','platform');if(b.dataset.page==='settings'){state.mode='staff';state.page='attendance';v3.attendanceTab='policy';closeModal();render();return;}if(b.dataset.page==='access'){v3.peopleTab='roles';return go('people','staff');}}
 if(a==='mode'){v3.expanded=null;v3.personFilter='all';}
 if(a==='exit-preview'){await baseV3.handleAction(b);v3.peopleTab='roles';state.page='people';render();return;}
 if(a==='people-tab'){v3.peopleTab=value;render();return;}
 if(a==='attendance-view'){v3.attendanceTab=value;render();return;}
 if(a==='person-overview'){if(!canTeam()&&id!==me().id)return;modal(t('Overview','Overview')+' · '+person(id).name,personalOverview(id),true);return;}
 if(a==='internal-review'){if(!me().super)return;const x=data.leaves.find(x=>x.id===id);if(!x)return;modal(t('Pengajuan cuti','Leave request'),`${personCell(person(x.staff))}<div class="notice space">${date(x.start)} – ${date(x.end)} · ${x.days} ${t('hari kerja','working days')}</div><p>${esc(splitLabel(x.reason))}</p><div class="inline space">${btn(t('Setujui','Approve'),'leave-decision',`data-id="${id}"`,'primary')}${btn(t('Tolak','Decline'),'leave-reject',`data-id="${id}"`,'small')}</div>`);return;}
 if(a==='leave-decision'){await baseV3.handleAction(b);closeModal();return;}
 if(a==='stat-detail'){let list=operationalTasks();if(id==='done'){const items=todayRecords().filter(x=>canTeam()||x.staff===me().id);return modal(t('Hasil hari ini','Today’s outcomes'),items.map(x=>`<div class="row"><div><strong>${esc(x.title)}</strong><small>${person(x.staff).name} · ${x.time} WIB</small></div>${badge(t('Tahap selesai','Stage completed'),'green')}</div>`).join('')||empty(t('Belum ada hasil tercatat','No recorded outcomes')));}list=list.filter(x=>id==='new'?x.stage==='queued':id==='waiting'?waiting(x):id==='overdue'?x.stage!=='approval'&&taskAttention(x):x.stage!=='queued');return modal(t('Rincian pekerjaan','Work details'),list.map(x=>`<div class="row"><div><strong>${esc(splitLabel(x.title))}</strong><small>${stageName(x.stage)}</small></div>${btn(t('Lihat','View'),'task',`data-id="${x.id}"`,'small')}</div>`).join('')||empty(t('Tidak ada pekerjaan','No items')));}
 if(a==='priorities')return prioritiesModal();
 if(a==='rule-edit')return ruleModal(id);
 if(a==='op-detail')return opModal(id);
 if(a==='op-reject'){if(!me().super||previewBlocked())return;const x=data.ops.find(x=>x.id===id),reason=$('form[data-form="op-decision"] textarea')?.value.trim();if(!reason)return feedback(t('Tuliskan alasan keputusan.','Enter a decision reason.'));x.status='rejected';log(t('Permintaan ditolak','Request declined'),x.id+' · '+reason);closeModal();render();return;}
 if(a==='coverage')return modal(t('Cakupan pekerjaan V3','V3 workflow coverage'),`<p class="sub">${t('Katalog aturan mencakup 11 kelompok. Interaksi contoh tersedia untuk rilisan, klaim, tiket, verifikasi, penarikan, cuti, koreksi kehadiran, dan slip. Halaman operasional lengkap tetap Part 2.','The rule catalog covers 11 groups. Sample interactions cover releases, claims, tickets, verification, withdrawals, leave, attendance corrections, and payslips. Full operational pages remain Part 2.')}</p><div class="notice space">${t('Audit repo menemukan celah pada metadata approval, refund, layanan khusus, payroll, dan pembayaran penarikan. V3 mendemonstrasikan pendekatan; integrasi backend masih perlu pekerjaan tersendiri.','The repository audit found gaps in metadata approval, refunds, custom services, payroll, and payout completion. V3 demonstrates the approach; backend integration remains separate work.')}</div>`);
 if(a==='simulate')return simulateModal();
 if(['sim-chat','sim-notification','sim-believe'].includes(a)){if(previewBlocked())return;
  if(a==='sim-chat'){if(permission('support')==='none'){data.chats.internal.push({who:'eka',text:['Catatan pemeriksaan sudah dilengkapi. Silakan lihat konteks pekerjaan.','Review notes are complete. Please check the work context.']});state.chat='internal';}else{data.chats.label.push({who:'Senja Records',text:['Terima kasih, dokumen koreksi sudah kami kirim. Mohon diperiksa kembali.','Thank you. We have sent the corrected documents. Please review them.']});state.chat='label';}v3.chatUnread++;closeModal();render();toast(t('Pesan baru masuk · buka Chat','New message received · open Chat'));return;}
  if(a==='sim-notification'){addNotification(me().id,['Hasil pemeriksaan tersedia','Review outcome available'],['Ada catatan baru yang perlu kamu lihat. Buka pekerjaan terkait.','New notes are ready for review. Open the related work.'],'profile');closeModal();render();toast(t('Notifikasi baru masuk','New notification received'));return;}
  const x=data.tasks.find(x=>x.id==='R-1048');if(!x||x.stage==='done')return toast(t('Pekerjaan ini sudah selesai.','This work is already complete.'));x.stage='review';x.responseReceived=true;x.pct=75;x.due=addWorkingDays(day(),1);data.events.unshift({id:Date.now(),who:null,obj:x.id,text:['Balasan Believe diterima; perlu pemeriksaan internal','Believe replied; internal review needed'],time:'12.05',day:day(),category:'work'});addNotification('all',['Balasan Believe diterima','Believe response received'],['Kumari kembali memerlukan pemeriksaan.','Kumari requires another review.'],'dashboard');data.notifications[0].obj=x.id;data.notifications[0].permission='release';closeModal();render();toast(t('Status diperbarui dari balasan simulasi','Status updated from the simulated response'));return;
 }
 if(a==='slip-new')return slipForm();if(a==='slip-edit')return slipForm(id);if(a==='slip-download')return slipDownload(id);
 if(['slip-copy','slip-issue','slip-delete','slip-void'].includes(a)){if(!me().super||previewBlocked())return;const x=data.slips.find(x=>x.id===id);if(!x)return;if(a==='slip-copy'){const n=Staff118.copySlip(data,id,id118,day());return slipForm(n.id);}if(a==='slip-issue'&&x.status==='draft'){Staff118.issue(data,id,day(),me().id);log(t('Slip diterbitkan','Payslip issued'),x.id);}if(a==='slip-delete'&&x.status==='draft'){data.slips=data.slips.filter(s=>s.id!==id);log(t('Draf slip dihapus','Payslip draft deleted'),id);}if(a==='slip-void'&&x.status==='issued'){modal(t('Batalkan dokumen','Cancel document'),`<form data-form="void-slip" data-id="${id}"><p class="sub">${t('Versi tetap ada di riwayat. Catatan pembayaran tidak berubah.','The version remains in history. Payment records are unchanged.')}</p>${reasonField()}${formEnd(t('Batalkan slip','Cancel payslip'))}</form>`);return;}render();return;}
 if(a==='reset'){if(previewBlocked())return;data=initial();seedV3();v3.scenario='today';v3.day='2026-09-18';v3.expanded=null;closeModal();render();toast(t('Simulasi dikembalikan ke awal.','Simulation reset.'));return;}
 return baseV3.handleAction(b);
};
handleSubmit=async function(f){const a=f.dataset.form,id=f.dataset.id,v=new FormData(f);if(!f.reportValidity())return;
 if(a==='task-action'){const x=visibleTasks().find(x=>x.id===id);if(x?.stage==='approval'&&!me().super)return feedback(t('Keputusan ini memerlukan Super Admin.','This decision requires a Super Admin.'));}
 if(['work-rule','op-decision','slip','void-slip'].includes(a)&&(!me().super||previewBlocked()))return;
 if(a==='followup'){const x=data.tasks.find(x=>x.id===id);if(!x)return;return doOperation(x.kind,t('Tindak lanjut','Follow-up')+' · '+id,{type:'followup',id,expected:x.stage,note:String(v.get('reason'))});}
 if(a==='work-rule'){const r=data.workRules.find(x=>x.id===id),n=Number(v.get('value')),end=Number(v.get('end'));if(r.mode==='monthly'&&end<n)return feedback(t('Akhir periode harus setelah tanggal mulai.','The end must be after the start.'));if(r.mode==='nextday')r.immediate=v.get('nextday')==='same';else r.value=n;if(r.mode==='monthly')r.end=end;r.weight=Number(v.get('weight'));r.version++;log(t('Aturan baru disimpan','New rule saved'),L(r.name)+' · '+v.get('reason'));closeModal();render();toast(t('Aturan tersimpan untuk pekerjaan baru.','Rule saved for new work.'));return;}
 if(a==='op-decision'){const x=data.ops.find(x=>x.id===id);if(!x||!['pending','approved'].includes(x.status))return;if(x.kind==='withdraw')x.status=x.status==='pending'?'approved':'paid';else x.status='approved-done';x.note=String(v.get('reason'));x.decidedBy=me().id;x.decidedAt=day();data.events.unshift({id:Date.now(),who:me().id,obj:x.id,text:[L(x.title)+' · '+statusName(x.status),L(x.title)+' · '+statusName(x.status)],time:'12.00',day:day(),category:'work'});log(t('Keputusan tercatat','Decision recorded'),id+' · '+x.note);closeModal();render();toast(t('Tahap diperbarui dalam simulasi.','Stage updated in the simulation.'));return;}
 if(a==='slip'){let x=data.slips.find(s=>s.id===id);if(x&&x.status!=='draft')return;const staff=String(v.get('staff')),m=String(v.get('month')),adjust=Number(v.get('adjust'));x=Staff118.saveSlip(data,id,{staff,month:m,adjust,note:String(v.get('note'))},payments(staff,m).filter(r=>r.published!==false),id118,day());log(t('Draf slip disimpan','Payslip draft saved'),x.id);closeModal();render();return;}
 if(a==='void-slip'){const x=data.slips.find(x=>x.id===id);if(x){x.status='void';x.voidReason=String(v.get('reason'));log(t('Slip dibatalkan','Payslip cancelled'),x.id+' · '+x.voidReason);}closeModal();render();return;}
 return baseV3.handleSubmit(f);
};
document.addEventListener('change',e=>{if(e.target.id==='scenario'){if(state.preview)return;v3.scenario=e.target.value;v3.day=({today:'2026-09-18',tomorrow:'2026-09-19',payout:'2026-09-15',late:'2026-09-21',quiet:'2026-09-18',busy:'2026-09-18'})[v3.scenario];if(v3.scenario!=='busy')data.tasks=data.tasks.filter(x=>!x.demoExtra);if(v3.scenario==='busy'&&!data.tasks.some(x=>x.demoExtra)){for(let i=0;i<6;i++)data.tasks.push({id:'R-DEMO-'+i,title:titles[i]+' II',kind:'release',stage:'queued',pct:0,handler:null,last:null,label:'Senja Records',created:day(),due:'2026-09-21',demoExtra:true});}render();}if(e.target.id==='handler-filter'){v3.personFilter=e.target.value;render();}});
document.addEventListener('keydown',e=>{if(e.target.matches('.calendar .date')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.click();}});
document.addEventListener('input',e=>{if(e.target.closest('form[data-form="work-rule"]'))ruleExample();});
document.addEventListener('click',e=>{const c=e.target.closest('.calendar .date');if(c)modal(t('Catatan kehadiran','Attendance record'),`<p>${esc(c.title)}</p><p class="sub">${t('Catatan simulasi periode terpilih. Ajukan koreksi jika terdapat ketidaksesuaian.','Simulated record for the selected period. Request a correction if it is inaccurate.')}</p>${btn(t('Ajukan koreksi','Request correction'),'attendance-correction','','small')}`);});

const applyBeforeV3=applyOperation;
applyOperation=function(op){if(op.type!=='followup')return applyBeforeV3(op);const x=data.tasks.find(x=>x.id===op.id);if(!x||x.stage!==op.expected)return false;const rule=data.workRules.find(r=>r.id===(x.stage==='believe'?'believe':'label'));x.due=addWorkingDays(day(),rule.value);x.ruleVersion=rule.version;x.last=day()+'T12:00:00';x.handler=me().id;data.events.unshift({id:Date.now(),who:me().id,obj:x.id,text:[op.note,op.note],time:'12.00',day:day(),category:'work'});log(t('Tindak lanjut dicatat','Follow-up recorded'),x.id);return true;};
function myDecisionRows(){return operationalTasks().filter(x=>x.stage==='approval').map(x=>'<div class="action-row"><div class="grow"><strong>'+esc(splitLabel(x.title))+'</strong><small>'+x.id+' · '+t('Persetujuan rilisan','Release approval')+'</small></div>'+btn(t('Tinjau','Review'),'task','data-id="'+x.id+'"','small')+'</div>').join('')+data.requests.filter(x=>x.status==='pending').map(x=>'<div class="action-row"><div class="grow"><strong>'+esc(x.title)+'</strong><small>'+person(x.staff).name+'</small></div>'+btn(t('Tinjau','Review'),'review-request','data-id="'+x.id+'"','small')+'</div>').join('');}
const actionBeforeFinal=handleAction;
handleAction=async function(b){if(b.dataset.action==='payslip'){const x=data.slips.filter(x=>x.staff===b.dataset.id&&x.month===(b.dataset.month||state.period)&&x.status==='issued').sort((a,b)=>b.version-a.version)[0];if(x)return slipDownload(x.id);}if(b.dataset.action==='task'&&data.ops.some(x=>x.id===b.dataset.id))return opModal(b.dataset.id);if(b.dataset.action==='review-request'){v3.peopleTab='roles';return go('people','staff');}return actionBeforeFinal(b);};

// V4 performs the initial render.